config..claude-plugin/hooks.json:
{
  "description": "Auto-refresh expired Spotify OAuth tokens before API calls (Claude Code and Codex; Antigravity uses hooks.json at plugin root)",
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "bash \"${CODEX_PLUGIN_ROOT:-${CLAUDE_PLUGIN_ROOT:-.}}/hooks/check-token.sh\"",
            "timeout": 30
          }
        ]
      }
    ]
  }
}
